package io.mehow.laboratory.inspector.cmp

import io.mehow.laboratory.FeatureFactory
import io.mehow.laboratory.Laboratory

/**
 * Configuration for [LaboratoryInspector].
 *
 * @param laboratory the [Laboratory] instance that reads/writes the current feature-flag state.
 * @param featureFactories map of section-title to [FeatureFactory]. Each entry becomes a tab in the
 *   inspector. The [FeatureFactory] must have been generated by the Laboratory Gradle plugin so its
 *   `options()` registry can resolve feature enum entries without JVM reflection.
 * @param deprecationHandler controls how deprecated features are styled and ordered. Defaults to
 *   [DeprecationHandler.Default].
 */
public class LaboratoryConfiguration(
  public val laboratory: Laboratory,
  public val featureFactories: Map<String, FeatureFactory>,
  public val deprecationHandler: DeprecationHandler = DeprecationHandler.Default,
) {
  init {
    require(featureFactories.isNotEmpty()) {
      "LaboratoryConfiguration must have at least one feature factory section."
    }
  }

  /** Factory helpers for [LaboratoryConfiguration]. */
  public companion object {
    /** Convenience factory wrapping a single unnamed section. */
    public fun create(
      laboratory: Laboratory,
      featureFactory: FeatureFactory,
      sectionName: String = "Features",
      deprecationHandler: DeprecationHandler = DeprecationHandler.Default,
    ): LaboratoryConfiguration =
      LaboratoryConfiguration(
        laboratory = laboratory,
        featureFactories = mapOf(sectionName to featureFactory),
        deprecationHandler = deprecationHandler,
      )
  }
}
